static void stop_vma(struct seq_file *m, void *v)
{
    struct vma_iterator *vmi = seq_file_private(m);
    struct task_struct *task = vmi->task;

    if (!IS_ERR_OR_NULL(v))
        vma_stop(m, v);

    if (task)
        put_task_struct(task);
}

